import itertools
import random

N_GOLFERS = 24
N_WEEKS = 8
GROUP_SIZE = 3
N_GROUPS_PER_WEEK = 8

def check_schedule(schedule):
    """schedule[w][g] = group number for golfer g in week w"""
    pairs_used = set()
    for w in range(N_WEEKS):
        groups = [[] for _ in range(N_GROUPS_PER_WEEK)]
        for g in range(N_GOLFERS):
            grp = schedule[w][g]
            groups[grp].append(g)
        for grp in groups:
            if len(grp) != 3:
                return False
            for pair in itertools.combinations(grp, 2):
                pair_key = tuple(sorted(pair))
                if pair_key in pairs_used:
                    return False
                pairs_used.add(pair_key)
    return True

def try_random():
    for attempt in range(10000):
        schedule = [[-1] * N_GOLFERS for _ in range(N_WEEKS)]
        pairs_used = set()
        success = True

        for w in range(N_WEEKS):
            golfers = list(range(N_GOLFERS))
            random.shuffle(golfers)

            groups = []
            remaining = set(golfers)

            for g_idx in range(N_GROUPS_PER_WEEK):
                if not remaining:
                    success = False
                    break
                first = random.choice(list(remaining))
                remaining.remove(first)

                candidates = [g for g in remaining]
                random.shuffle(candidates)

                found = False
                for second in candidates:
                    if tuple(sorted([first, second])) in pairs_used:
                        continue
                    for third in candidates:
                        if third == second:
                            continue
                        if tuple(sorted([first, third])) in pairs_used:
                            continue
                        if tuple(sorted([second, third])) in pairs_used:
                            continue
                        group = [first, second, third]
                        groups.append(group)
                        remaining.remove(second)
                        remaining.remove(third)
                        for pair in itertools.combinations(group, 2):
                            pairs_used.add(tuple(sorted(pair)))
                        found = True
                        break
                    if found:
                        break

                if not found:
                    success = False
                    break

            if not success:
                break

            for g_idx, group in enumerate(groups):
                for golfer in group:
                    schedule[w][golfer] = g_idx

        if success:
            return schedule
        if attempt % 1000 == 0:
            print(f"Attempt {attempt}...")

    return None

print("Trying random search...")
result = try_random()
if result:
    print("Found solution!")
    flat = []
    for w in range(N_WEEKS):
        for g in range(N_GOLFERS):
            flat.append(result[w][g])
    print(flat)
    print("Check:", check_schedule(result))
else:
    print("No solution found with random search")
